# owner: platform
import unittest

from hourglass.models import Span
from hourglass.rounding import label_rounded_spans


class LabelTests(unittest.TestCase):
    def test_rounds_to_nearest_step(self):
        labels = label_rounded_spans([Span(541, 1036)], 15)
        self.assertEqual(labels, ["09:00-17:15 (8h 15m)"])

    def test_halfway_rounds_up(self):
        labels = label_rounded_spans([Span(541, 600)], 2)
        self.assertEqual(labels, ["09:02-10:00 (0h 58m)"])

    def test_several_spans_keep_order(self):
        spans = [Span(547, 608), Span(780, 1020)]
        labels = label_rounded_spans(spans, 15)
        self.assertEqual(
            labels,
            ["09:00-10:15 (1h 15m)", "13:00-17:00 (4h 0m)"]
        )

    def test_empty_list(self):
        self.assertEqual(label_rounded_spans([], 15), [])

    def test_bad_steps(self):
        for step in (0, -15, 7, 120):
            with self.subTest(step=step):
                with self.assertRaises(ValueError):
                    span = Span(540, 600)
                    label_rounded_spans([span], step)

    def test_span_collapsing_to_zero_is_rejected(self):
        with self.assertRaises(ValueError):
            label_rounded_spans([Span(541, 545)], 15)
